import ast, json, os, re, sys
ROOT='services'
CLAUSES=[f'C{i}' for i in range(1,16)]

def is_lfs(path):
    try:
        with open(path,'rb') as f: first=f.readline()
        return first.rstrip(b'\r\n')==b'version https://git-lfs.github.com/spec/v1'
    except OSError: return False

def py_files(d):
    out=[]
    for base,_,files in os.walk(os.path.join(d,'src')):
        for fn in files:
            if fn.endswith('.py'): out.append(os.path.join(base,fn))
    return sorted(out)

def check(d, cfg):
    v=[]; notes={}
    # C1
    if cfg.get('exposure')=='public' and not (isinstance(cfg.get('timeout_s'),(int,float)) and not isinstance(cfg.get('timeout_s'),bool) and cfg.get('timeout_s')<=30):
        v.append('C1')
    # C2, C3, C9, C10 handler
    hpath=os.path.join(d,'src','handlers.py')
    tree=None
    try:
        src=open(hpath,encoding='utf-8').read(); tree=ast.parse(src)
    except Exception as e:
        notes['handlers_parse']=str(e)
    c2=True
    if tree:
        for n in ast.walk(tree):
            if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith('handle_'):
                if ast.get_docstring(n) is None: c2=False; notes.setdefault('C2',[]).append(n.name)
    if not c2: v.append('C2')
    # C3 print calls in src
    c3=True
    for p in py_files(d):
        try: t=ast.parse(open(p,encoding='utf-8').read())
        except Exception: continue
        for n in ast.walk(t):
            if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='print':
                c3=False; notes.setdefault('C3',[]).append(p); break
    if not c3: v.append('C3')
    # C4
    r=cfg.get('retries')
    if not (isinstance(r,int) and not isinstance(r,bool) and 1<=r<=5): v.append('C4')
    # C5
    df=os.path.join(d,'Dockerfile'); lines=open(df,encoding='utf-8').read().splitlines()
    from_lines=[l for l in lines if re.match(r'^\s*FROM\s',l,re.I)]
    c5=all(re.search(r'@sha256:[0-9a-f]{64}(?![0-9a-fA-Z])',l) for l in from_lines) and bool(from_lines)
    if not c5: v.append('C5')
    # C6
    users=[l for l in lines if re.match(r'^\s*USER\s',l,re.I)]
    if not users: v.append('C6')
    else:
        u=users[-1].split(None,1)[1].strip() if len(users[-1].split(None,1))>1 else ''
        uname=u.split(':')[0].split()[0] if u else ''
        if uname in ('root','0'): v.append('C6')
    # C7
    rl=open(os.path.join(d,'README.md'),encoding='utf-8').read().splitlines()
    if '## Runbook' not in rl: v.append('C7')
    # C8
    co=open(os.path.join(d,'CODEOWNERS'),encoding='utf-8').read().splitlines()
    star=[l for l in co if l.strip() and not l.lstrip().startswith('#') and l.split()[0]=='*']
    want='@team-'+str(cfg.get('team'))
    c8=any(l.split()[1:]==[want] or want in l.split()[1:] for l in star)
    if not c8: v.append('C8')
    # C9
    c9=True
    for p in py_files(d):
        try: t=ast.parse(open(p,encoding='utf-8').read())
        except Exception: continue
        for n in ast.walk(t):
            if isinstance(n,ast.Constant) and isinstance(n.value,str) and (n.value.startswith('sk_live_') or n.value.startswith('AKIA')):
                c9=False; notes.setdefault('C9',[]).append((p,n.value[:12])); break
    if not c9: v.append('C9')
    # C10
    hc=cfg.get('healthcheck')
    seg=str(hc).rstrip('/').split('/')[-1] if isinstance(hc,str) and str(hc).strip() else None
    if hc is None or not seg: v.append('C10')
    elif tree is not None:
        names={n.name for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
        if 'handle_'+seg not in names: v.append('C10'); notes.setdefault('C10',[]).append('handle_'+seg)
    else: v.append('C10')
    # C11
    if cfg.get('metrics_port')==cfg.get('port'): v.append('C11')
    # C12
    req=open(os.path.join(d,'requirements.txt'),encoding='utf-8').read().splitlines()
    c12=True
    for l in req:
        s=l.strip()
        if not s or s.startswith('#'): continue
        if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._-]*(\[[A-Za-z0-9,._-]+\])?==[A-Za-z0-9][A-Za-z0-9._+-]*',s):
            c12=False; notes.setdefault('C12',[]).append(l); break
    if not c12: v.append('C12')
    # C13
    if cfg.get('log_level')=='DEBUG': v.append('C13')
    # C14
    if cfg.get('exposure')=='public':
        mb=cfg.get('max_body_kb')
        if not (isinstance(mb,(int,float)) and not isinstance(mb,bool) and mb<=1024): v.append('C14')
    # C15
    td=os.path.join(d,'tests')
    if not (os.path.isdir(td) and any(fn.startswith('test_') and fn.endswith('.py') for fn in os.listdir(td))): v.append('C15')
    return v,notes

for name in sorted(os.listdir(ROOT)):
    d=os.path.join(ROOT,name)
    if not os.path.isdir(d): continue
    allfiles=[]
    for base,dirs,files in os.walk(d):
        dirs[:]=[x for x in dirs if x!='.git']
        for fn in files: allfiles.append(os.path.join(base,fn))
    lfs=[f for f in allfiles if is_lfs(f)]
    cfg=json.load(open(os.path.join(d,'config.json')))
    if lfs:
        print(name,'UNVERIFIABLE',lfs)
    else:
        v,notes=check(d,cfg)
        print(name, json.dumps(v), json.dumps(notes))
